import React, { useEffect, useState } from "react";

function SavedPage({ token }) {
  const [saved, setSaved] = useState([]);

  useEffect(() => {
    if (!token) return;
    fetch("http://127.0.0.1:8000/api/saved/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then(setSaved)
      .catch(console.error);
  }, [token]);

  if (!token) return <p>Увійдіть, щоб переглянути збережене.</p>;

  return (
    <div className="saved-container">
      <h2>📚 Збережені статті</h2>
      {saved.length === 0 ? (
        <p>Немає збережених статей.</p>
      ) : (
        <ul>
          {saved.map((s) => (
            <li key={s.id}>
              <a href={`/article/${s.article}`}>Стаття #{s.article}</a>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default SavedPage;
